package org.marketreview.nativeapp;
import org.json.*;
import java.time.Instant;
import java.util.Arrays;
public final class AiSettingsCapabilities {
 private AiSettingsCapabilities(){}
 static String name(String id){String[] ids={"local-factor-v1","local-factor-lab-v1","local-ma-strategy-lab-v1","evidence-orchestrator-v1","local-paper-portfolio-v1","knowledge-fts-v1","chatgpt-handoff","openai-direct","qlib-lightgbm","qlib-master","alphaagent","rd-agent-q","tradingagents","finrl-x"},names={"本地选股因子","本地因子研究","均线策略研究","证据研究编排","模拟投资组合","资料全文检索","ChatGPT 手动交接","直接 AI 接口","Qlib / LightGBM","Qlib / MASTER","AlphaAgent","RD-Agent-Q","TradingAgents","FinRL-X"};for(int n=0;n<ids.length;n++)if(ids[n].equals(id))return names[n];return id;}
 static void validateReports(JSONArray input)throws Exception{AiSettingsModel.need(input.length()<=100,"能力记录过多");for(int n=0;n<input.length();n++){JSONObject o=input.optJSONObject(n);AiSettingsModel.need(o!=null,"能力证据无效");String[] keys={"id","status","claimedStatus","source","sourceObservedAt","checkedAt","importedAt"};java.util.Iterator<String> names=o.keys();while(names.hasNext())AiSettingsModel.need(Arrays.asList(keys).contains(names.next()),"能力证据字段无效");AiSettingsModel.need(o.length()==7&&o.optString("status").equals("reported-unverified")&&Arrays.asList("import","host").contains(o.optString("source"))&&o.isNull("sourceObservedAt")&&o.isNull("checkedAt"),"能力证据范围无效");String id=o.optString("id","");AiSettingsModel.need(id.matches("[a-zA-Z0-9][a-zA-Z0-9._-]{0,80}")&&!java.util.regex.Pattern.compile("(sk-|bearer|api[_-]?key|password|authorization)",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(id).find(),"能力标识无效");AiSettingsModel.need(Arrays.asList("available","configured","not_configured","planned","unavailable","validated","hash_verified","metadata_valid","declaration-only","unknown").contains(o.optString("claimedStatus")),"能力来源状态无效");String at=o.optString("importedAt","");try{AiSettingsModel.need(at.length()<=32&&at.endsWith("Z"),"能力记录时间无效");Instant.parse(at);}catch(Exception e){throw new Exception("能力记录时间无效");}}}
 static JSONArray declarations()throws Exception{JSONArray a=new JSONArray();for(String id:new String[]{"local-factor-v1","local-factor-lab-v1","local-ma-strategy-lab-v1","evidence-orchestrator-v1","local-paper-portfolio-v1","knowledge-fts-v1","chatgpt-handoff","openai-direct","qlib-lightgbm","qlib-master","alphaagent","rd-agent-q","tradingagents","finrl-x"})a.put(new JSONObject().put("id",id).put("status","declaration-only").put("source","services/modelRegistryService.js").put("sourceObservedAt",JSONObject.NULL).put("checkedAt",JSONObject.NULL));return a;}
 static JSONArray reported(JSONArray input,String origin)throws Exception{JSONArray out=new JSONArray();if(input==null)return out;AiSettingsModel.need(input.length()<=100,"能力记录过多");for(int n=0;n<input.length();n++){JSONObject o=input.optJSONObject(n);AiSettingsModel.need(o!=null,"能力记录无效");String id=o.optString("id","");AiSettingsModel.need(id.matches("[a-zA-Z0-9][a-zA-Z0-9._-]{0,80}")&&!java.util.regex.Pattern.compile("(sk-|bearer|api[_-]?key|password|authorization)",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(id).find(),"能力标识无效");String claimed=o.optString("status","").equals("reported-unverified")?o.optString("claimedStatus",""):o.optString("status","");if(!Arrays.asList("available","configured","not_configured","planned","unavailable","validated","hash_verified","metadata_valid","declaration-only").contains(claimed))claimed="unknown";out.put(new JSONObject().put("id",id).put("status","reported-unverified").put("claimedStatus",claimed).put("source",origin).put("sourceObservedAt",JSONObject.NULL).put("checkedAt",JSONObject.NULL).put("importedAt",Instant.now().toString()));}return out;}
}
